@check(label='ch:iams_law:L270', chapter='ch:iams_law', part=1, title='eta from the structural identity times dA_min from the first law with one Unruh quantum is 1 nat',
       file='part1/p1_02_iams_law', line=270, status='derived', kind='sym', printed='1', tol=0.0)
def check_0079():
    'eta from the structural identity times dA_min from the first law with one Unruh quantum is 1 nat. Book line 270, printed 1.'
    hb,c_,G_,kap,eta=sp.symbols('hbar c G kappa eta',positive=True)
    eta_s=sp.solve(sp.Eq(hb*eta/(2*sp.pi), c_**3/(8*sp.pi*G_)), eta)[0]  # from the structural identity
    dA=(8*sp.pi*G_/(kap*c_**2))*(hb*kap/(2*sp.pi*c_))  # first law dA = 8 pi G dM c^2/(kappa c^4) with one Unruh quantum hbar kappa/(2 pi c)
    lhs=eta_s*dA; rhs=sp.Integer(1)
    _wrong=eta_s*dA.subs(c_,1)*c_-1
    assert sp.simplify(_wrong)!=0, 'negative control did not fail'
    return locals()

