@check(label='eq:law_hoop', chapter='ch:iams_law', part=1, title='S_BH/A at Schwarzschild radius equals holographic bound',
       file='part1/p1_02_iams_law', line=634, status='derived', kind='sym', printed='', tol=0.0)
def check_0138():
    'S_BH/A at Schwarzschild radius equals holographic bound (Eq. eq:law_hoop). Book line 634.'
    G_s,kB_s,M_s,hbar_s,c_s=sp.symbols('G kB M hbar c',positive=True); S_BH=4*sp.pi*G_s*kB_s*M_s**2/(hbar_s*c_s); r_s=2*G_s*M_s/c_s**2; A=4*sp.pi*r_s**2; lhs=S_BH/A; rhs=kB_s*c_s**3/(4*hbar_s*G_s)
    return locals()

@check(label='eq:law_Meq', chapter='ch:iams_law', part=1, title='equilibrium mass from T_BH=T_H',
       file='part1/p1_02_iams_law', line=643, status='derived', kind='sym', printed='', tol=0.0)
def check_0139():
    'equilibrium mass from T_BH=T_H (Eq. eq:law_Meq). Book line 643.'
    M,H,G,c,hbar,kB=sp.symbols('M H G c hbar kB',positive=True); T_BH=hbar*c**3/(8*sp.pi*G*M*kB); T_H=hbar*H/(2*sp.pi*kB); lhs=sp.solve(sp.Eq(T_BH,T_H),M)[0]; rhs=c**3/(4*G*H)
    return locals()

@check(label='ch:iams_law:L645', chapter='ch:iams_law', part=1, title='ratio identity T_BH/T_H=Meq/M',
       file='part1/p1_02_iams_law', line=645, status='derived', kind='sym', printed='', tol=0.0)
def check_0140():
    'ratio identity T_BH/T_H=Meq/M. Book line 645.'
    M,H,G,c,hbar,kB=sp.symbols('M H G c hbar kB',positive=True); T_BH=hbar*c**3/(8*sp.pi*G*M*kB); T_H=hbar*H/(2*sp.pi*kB); M_eq=c**3/(4*G*H); lhs=T_BH/T_H; rhs=M_eq/M
    return locals()

