@check(label='ch:s8trend:L85:1.68', chapter='ch:s8trend', part=2, title='drafted check, screened (runs; negative control fails)',
       file='part2/p2_08_s8_trend', line=85, status='calc', kind='num', printed='1.68', tol=0.0)
def check_0863():
    'drafted check, screened (runs; negative control fails). Book line 85, printed 1.68.'
    # Line 85: S_8 inferred for MGCAMB form at z=0, as per cent deficit from Planck value
