def _limber_out():
    t = open(REPO / "docs/verification/scripts/verify_limber_lensing_output.txt", encoding="utf-8").read()
    m = re.search(r"30 <= L <= 1000: ([0-9.]+) - ([0-9.]+) %", t)
    return float(m.group(1)), float(m.group(2))

