    u=sp.symbols('u',real=True); Eu=sp.exp(1-sp.exp(-u)); d2=sp.diff(Eu,u,2); sol=sp.solve(sp.Eq(d2,0),u); ok = 0 in [sp.nsimplify(s) for s in sol]
