@check(label='ch:surveys:L159', chapter='ch:surveys', part=2, title='drafted check, screened (runs; negative control fails)',
       file='part2/p2_16_survey_predictions', line=159, status='calc', kind='num', printed='+1.8', tol=0.0)
def check_1577():
    'drafted check, screened (runs; negative control fails). Book line 159, printed +1.8.'
    # E_G = Ω_m0 Σ / f; rises because f falls while lensing (Σ) does not
    # At z=0.3: E_G_iam / E_G_lcdm - 1, expressed as per cent
    f_iam = f_of("iam", 0.3)
    f_lcdm = f_of("lcdm", 0.3)
    # Σ=1 for both; Ω_m0 same; only f differs
    E_G_ratio = f_lcdm / f_iam  # f falls in IAM → E_G rises
    value = 100 * (E_G_ratio - 1)
    return locals()

@check(label='ch:surveys:L159:+3.6', chapter='ch:surveys', part=2, title='drafted check, screened (runs; negative control fails)',
       file='part2/p2_16_survey_predictions', line=159, status='calc', kind='num', printed='+3.6', tol=0.0)
def check_1578():
    'drafted check, screened (runs; negative control fails). Book line 159, printed +3.6.'
