    f_iam_z0 = f_of("iam", 0.0)
    f_lcdm_z0 = f_of("lcdm", 0.0)
    E_G_ratio_z0 = f_lcdm_z0 / f_iam_z0
    value = 100 * (E_G_ratio_z0 - 1)
    return locals()

