@check(label='eq:tw_adot', chapter='ch:threeway', part=2, title='drafted check, screened (runs; negative control fails)',
       file='part2/p2_18_three_way_clusters', line=48, status='derived', kind='sym', printed='', tol=0.0)
def check_1724():
    'drafted check, screened (runs; negative control fails) (Eq. eq:tw_adot). Book line 48.'
    a = sp.Symbol('a', positive=True, real=True)
    rho_tot = sp.Symbol('rho_tot', positive=True, real=True)
    beta_m = sp.Symbol('beta_m', positive=True, real=True)
    rho_0 = sp.Symbol('rho_0', positive=True, real=True)

    # Book's printed result: Eq. (2.18)
    # (da/dt) / a |_matter = a * sqrt((rho_tot + beta_m*E(a)*rho_0) / 3)
    # where E(a) = exp(1 - 1/a)

    E_of_a = sp.exp(1 - 1/a)
    lhs = sp.sqrt((rho_tot + beta_m * E_of_a * rho_0) / 3)

    # Book's printed result (what we verify)
    rhs = sp.sqrt((rho_tot + beta_m * sp.exp(1 - 1/a) * rho_0) / 3)

    # Variant with one coefficient perturbed: multiply the exponent's constant by 1.05
    rhs_wrong = sp.sqrt((rho_tot + beta_m * sp.exp(1.05 - 1/a) * rho_0) / 3)
    return locals()

