def check_1916():
    'solid angle 4 pi (Eq. eq:bk_solid). Book line 178.'
    th,ph=sp.symbols('vartheta varphi'); Om4=sp.integrate(sp.integrate(sp.sin(th),(th,0,sp.pi)),(ph,0,2*sp.pi)); ok=Om4==4*sp.pi
