@check(label='ch:reach:L90', chapter='ch:reach', part=7, title='drafted check, screened (runs; negative control fails)',
       file='part7/p7_09_reach', line=90, status='calc', kind='num', printed='6.2\\times10^{-7}', tol=0.0)
def check_2626():
    'drafted check, screened (runs; negative control fails). Book line 90, printed 6.2\\times10^{-7}.'
    # Line 90: per-gate floor p_eq * t_g / T_1
    # 5 GHz transmon at 35 mK with T_1 = 68 µs, gate time = 40 ns
    # p_eq from thermal floor: (gap / kB T) in the qubit bath

    # Gap for 5 GHz transmon
    f_qubit = 5e9  # Hz
    gap = h * f_qubit  # J

    # Bath temperature
    T_bath = 35e-3  # K (35 mK)

    # Thermal occupancy p_eq = 1 / (exp(gap / kB T) - 1)
    p_eq = 1.0 / (np.exp(gap / (kB * T_bath)) - 1.0)

    # Gate parameters
    t_g = 40e-9  # s (40 ns)
    T1 = 68e-6  # s (68 µs)

    # Per-gate floor
    floor = p_eq * t_g / T1

    value = floor
    return locals()

@check(label='ch:reach:L92', chapter='ch:reach', part=7, title='drafted check, screened (runs; negative control fails)',
       file='part7/p7_09_reach', line=92, status='calc', kind='num', printed='1.05\\times10^{-3}', tol=0.0)
def check_2627():
    'drafted check, screened (runs; negative control fails). Book line 92, printed 1.05\\times10^{-3}.'
    # Line 91-92: held-record floor at T = 35 mK (original temperature)
    # The held-record floor is the long-time relaxation floor when the qubit
    # is held in |e⟩: floor ~ p_eq * (T1 >> t_g case, continuous exposure)

    # At 35 mK
    T_bath = 35e-3  # K
    f_qubit = 5e9  # Hz
    gap = h * f_qubit
    p_eq = 1.0 / (np.exp(gap / (kB * T_bath)) - 1.0)

    # Held-record floor approximates to p_eq (dimensionless quasiparticle density)
    # or the equivalent error rate in a long hold. The text says p_eq * t_g / T1
    # for gate ops; for a held state over time t_hold, the floor is approximately p_eq.
    # At 35 mK, p_eq itself is the fractional floor:

    floor_35mK = p_eq

    value = floor_35mK
    return locals()

