@check(label='ch:conclusion:L23', chapter='ch:conclusion', part=7, title='same value as p4_15a_lepton_koide:33 (Koide Q, PDG 2024 masses)',
       file='part7/p7_10_conclusion', line=23, status='observed', kind='num', printed='0.66666446', tol=0)
def check_2684():
    'same value as p4_15a_lepton_koide:33 (Koide Q, PDG 2024 masses). Book line 23, printed 0.66666446.'
    me_,mmu_=0.51099895000,105.6583755  # CODATA 2018 / PDG 2024, MeV
    mtau24,stau24=1776.93,0.09; mtau22,stau22=1776.86,0.12  # PDG 2024, PDG 2022
    def Qk(a,b,cc): return (a+b+cc)/(math.sqrt(a)+math.sqrt(b)+math.sqrt(cc))**2
    def koide(mt):
        s=[math.sqrt(mt),math.sqrt(me_),math.sqrt(mmu_)]; x=sum(s)/3; Q=Qk(me_,mmu_,mt); r=math.sqrt(2*(3*Q-1)); d=math.acos((s[0]/x-1)/r); return x,r,d,Q
    def exact23():
        f=lambda v: [v[0]*(1+math.sqrt(2)*math.cos(v[1]+2*math.pi/3))-math.sqrt(me_), v[0]*(1+math.sqrt(2)*math.cos(v[1]+4*math.pi/3))-math.sqrt(mmu_)]
        from scipy.optimize import fsolve
        x,d=fsolve(f,[17.7,0.2222],xtol=1e-14); return x,d,(x*(1+math.sqrt(2)*math.cos(d)))**2
    value=Qk(me_,mmu_,mtau24)
    return locals()

@check(label='ch:conclusion:L23:0.43', chapter='ch:conclusion', part=7, title='Koide Q from 2/3, sigma',
       file='part7/p7_10_conclusion', line=23, status='observed', kind='num', printed='0.43', tol=0.0)
def check_4630():
    '(2/3 - Q)/sigma(Q) with Q of the PDG 2024 charged-lepton masses (m_e 0.51099895, m_mu 105.6583755, m_tau 1776.93 +- 0.09 MeV) and sigma(Q) propagated from sigma(m_tau). Book line 23, printed 0.43.'
    me_, mmu_, mt, st = 0.51099895000, 105.6583755, 1776.93, 0.09
    Qk = lambda t: (me_ + mmu_ + t) / (math.sqrt(me_) + math.sqrt(mmu_) + math.sqrt(t)) ** 2
    sQ = abs(Qk(mt + 1e-3) - Qk(mt - 1e-3)) / 2e-3 * st
    value = (2 / 3 - Qk(mt)) / sQ
    return locals()

