@check(label='app:derivations:L51:2.01824', chapter='app:derivations', part=8, title='omega_3^0 of the n = 3 Lane-Emden equation',
       file='appendices/app_C3_derivations', line=51, status='calc', kind='num', printed='2.01824', tol=0.0)
def check_4693():
    'The Lane-Emden constant omega_3^0 = -xi_1^2 theta(xi_1)prime for index n = 3, from integrating theta2prime + (2/xi) theta1prime = -theta^3 (theta(0) = 1) to its first zero xi_1. Book line 51, printed 2.01824. Inputs: none (Chandrasekhar 1931, the equation itself).'
    def le(xi, y):
        return [y[1], -y[0]**3 - 2 * y[1] / xi]
    x0 = 1e-6
    zero = lambda xi, y: y[0]
    zero.terminal = True
    s = solve_ivp(le, (x0, 10), [1 - x0**2 / 6, -x0 / 3], events=zero, rtol=1e-12, atol=1e-14)
    xi1 = s.t_events[0][0]; dth = s.y_events[0][0][1]
    value = -xi1**2 * dth
    return locals()

@check(label='app:derivations:L56', chapter='app:derivations', part=8, title='drafted check, screened (runs; negative control fails)',
       file='appendices/app_C3_derivations', line=56, status='derived', kind='sym', printed='', tol=0.0)
def check_2737():
    'drafted check, screened (runs; negative control fails). Book line 56.'
    M = sp.Symbol('M', positive=True, real=True)
    G_s = sp.Symbol('G', positive=True, real=True)
    hbar_s = sp.Symbol('hbar', positive=True, real=True)
    c_s = sp.Symbol('c', positive=True, real=True)
    k_B_s = sp.Symbol('k_B', positive=True, real=True)

    # Schwarzschild area
    A = 16 * sp.pi * G_s**2 * M**2 / c_s**4

    # Black hole entropy from S_BH = (k_B c^3 A) / (4 G hbar)
    S_BH = (k_B_s * c_s**3 * A) / (4 * G_s * hbar_s)
    S_BH_simplified = sp.simplify(S_BH)

    # Black hole temperature from T_BH S_BH = (1/2) M c^2
    # T_BH = hbar c^3 / (8 pi G k_B M)
    T_BH = hbar_s * c_s**3 / (8 * sp.pi * G_s * k_B_s * M)

    # Product T_BH * S_BH
    product = T_BH * S_BH_simplified
    product_simplified = sp.simplify(product)

    lhs = product_simplified
    rhs = sp.Rational(1, 2) * M * c_s**2
    rhs_wrong = sp.Rational(105, 100) * sp.Rational(1, 2) * M * c_s**2
    return locals()

